INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-nist-800-150-p2-1', 'doc-nist-800-150', '', 2, 'NIST Special Publication 800-150 Guide to Cyber Threat Information Sharing Chris Johnson Lee Badger David Waltermire Computer Security Division Information Technology Laboratory Julie Snyder Clem Skorupka The MITRE Corporation This publication is available free of charge from: http://dx.doi.org/10.6028/NIST.SP.800-150 October 2016 U.S. Department of Commerce Penny Pritzker, Secretary National Institute of Standards and Technology Willie May, Under Secretary of Commerce for Standards and Technology and Director', 'kb-doc-nist-800-150-p2-1', 0, 65, 'nist-sp-800-150', 'Final', '187E1CF8C4B60E21EDDF7A102DB2C1AF81E7F1F8CC40D3C46118032E4CB66128', 'v1', '{"source_id": "nist-sp-800-150", "version": "Final", "corpus_version": "v1", "batch": "batch-001"}')
