VALUES ('doc-nist-800-150-p4-1', 'doc-nist-800-150', '', 4, 'NIST SP 800-150 GUIDE TO CYBER THREAT INFORMATION SHARING ii This publication is available free of charge from: http://dx.doi.org/10.6028/NIST.SP.800-150', 'kb-doc-nist-800-150-p4-1', 0, 19, 'nist-sp-800-150', 'Final', 'BB5C988F736B047E7971C55EC974486D5ADD6EC44D9AA2EEF41AB552A901D6AB', 'v1', '{"source_id": "nist-sp-800-150", "version": "Final", "corpus_version": "v1", "batch": "batch-001"}')
