INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-nist-800-150-p5-1', 'doc-nist-800-150', '', 5, 'NIST SP 800-150 GUIDE TO CYBER THREAT INFORMATION SHARING iii This publication is available free of charge from: http://dx.doi.org/10.6028/NIST.SP.800-150', 'kb-doc-nist-800-150-p5-1', 0, 19, 'nist-sp-800-150', 'Final', '0224DA884D7B2E47BE58A408EB41F98B342AFEE8D8EE3C2A4F592EE9B31C92CA', 'v1', '{"source_id": "nist-sp-800-150", "version": "Final", "corpus_version": "v1", "batch": "batch-001"}')
