VALUES ('doc-nist-800-150-p11-1', 'doc-nist-800-150', '', 11, 'NIST SP 800-150 GUIDE TO CYBER THREAT INFORMATION SHARING 3 This publication is available free of charge from: http://dx.doi.org/10.6028/NIST.SP.800-150', 'kb-doc-nist-800-150-p11-1', 0, 19, 'nist-sp-800-150', 'Final', 'CF9D3A455357B5D3CFD323F15A81DC496B579698BBA3B80DEA605B71201A3B71', 'v1', '{"source_id": "nist-sp-800-150", "version": "Final", "corpus_version": "v1", "batch": "batch-001"}')
