VALUES ('doc-nist-800-150-p12-1', 'doc-nist-800-150', '', 12, 'NIST SP 800-150 GUIDE TO CYBER THREAT INFORMATION SHARING 4 This publication is available free of charge from: http://dx.doi.org/10.6028/NIST.SP.800-150', 'kb-doc-nist-800-150-p12-1', 0, 19, 'nist-sp-800-150', 'Final', 'B8E6C2742597FE21977163E9FD8D39AEF523D3A49754A2138CE65211273A9D66', 'v1', '{"source_id": "nist-sp-800-150", "version": "Final", "corpus_version": "v1", "batch": "batch-001"}')
