INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-nist-800-150-p14-1', 'doc-nist-800-150', '', 14, 'NIST SP 800-150 GUIDE TO CYBER THREAT INFORMATION SHARING 6 This publication is available free of charge from: http://dx.doi.org/10.6028/NIST.SP.800-150', 'kb-doc-nist-800-150-p14-1', 0, 19, 'nist-sp-800-150', 'Final', '1859021419D2972EA4242B8A9C6678C7DE817C4568F0E5DCEB2907066DA52E64', 'v1', '{"source_id": "nist-sp-800-150", "version": "Final", "corpus_version": "v1", "batch": "batch-001"}')
