INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-nist-800-150-p17-1', 'doc-nist-800-150', '', 17, 'NIST SP 800-150 GUIDE TO CYBER THREAT INFORMATION SHARING 9 This publication is available free of charge from: http://dx.doi.org/10.6028/NIST.SP.800-150', 'kb-doc-nist-800-150-p17-1', 0, 19, 'nist-sp-800-150', 'Final', 'CF7DFE6E91E8CEC8730FA6487F02753C249A3C81E1C0A8F0BEDD4C87D37B088E', 'v1', '{"source_id": "nist-sp-800-150", "version": "Final", "corpus_version": "v1", "batch": "batch-001"}')
