INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-nist-800-150-p22-1', 'doc-nist-800-150', '', 22, 'NIST SP 800-150 GUIDE TO CYBER THREAT INFORMATION SHARING 14 This publication is available free of charge from: http://dx.doi.org/10.6028/NIST.SP.800-150', 'kb-doc-nist-800-150-p22-1', 0, 19, 'nist-sp-800-150', 'Final', 'CBD0956C210F7F3599109E8B947790C1803557329F829863C895D007E182C1A9', 'v1', '{"source_id": "nist-sp-800-150", "version": "Final", "corpus_version": "v1", "batch": "batch-001"}')
