INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-nist-800-150-p23-1', 'doc-nist-800-150', '', 23, 'NIST SP 800-150 GUIDE TO CYBER THREAT INFORMATION SHARING 15 This publication is available free of charge from: http://dx.doi.org/10.6028/NIST.SP.800-150', 'kb-doc-nist-800-150-p23-1', 0, 19, 'nist-sp-800-150', 'Final', '3FF49B7D9D6AC93786F299702E1E01C3FC825415DB02EF3E9EB17E4DD4A98280', 'v1', '{"source_id": "nist-sp-800-150", "version": "Final", "corpus_version": "v1", "batch": "batch-001"}')
