VALUES ('doc-nist-800-150-p27-1', 'doc-nist-800-150', '', 27, 'NIST SP 800-150 GUIDE TO CYBER THREAT INFORMATION SHARING 19 This publication is available free of charge from: http://dx.doi.org/10.6028/NIST.SP.800-150', 'kb-doc-nist-800-150-p27-1', 0, 19, 'nist-sp-800-150', 'Final', 'F42B21038C4E42A374467CF4CEA79B60D12B087DBF04AD6AFE7DE502A19ECE00', 'v1', '{"source_id": "nist-sp-800-150", "version": "Final", "corpus_version": "v1", "batch": "batch-001"}')
