INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-nist-800-150-p27-2', 'doc-nist-800-150', '', 27, '• Collect and analyze the information from both internal and external sources, • Acquire and deploy protective measures, and • Acquire and deploy a monitoring and threat detection infrastructure. Organizations should provide funding for the personnel, infrastructure, and training required for ongoing operational support for data collection, storage, analysis, and dissemination; for technology refreshment; and for membership or service fees required for community participation. Although participation in information sharing activities will require ongoing funding, effective use of threat information may avoid the potentially much larger costs of successful attacks.', 'kb-doc-nist-800-150-p27-2', 0, 89, 'nist-sp-800-150', 'Final', 'B9457D0F99FC694A1B4FE4192671569640B3E093F8531C995E342D5605CB5401', 'v1', '{"source_id": "nist-sp-800-150", "version": "Final", "corpus_version": "v1", "batch": "batch-001"}')
