INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-nist-800-150-p29-1', 'doc-nist-800-150', '', 29, 'NIST SP 800-150 GUIDE TO CYBER THREAT INFORMATION SHARING 21 This publication is available free of charge from: http://dx.doi.org/10.6028/NIST.SP.800-150', 'kb-doc-nist-800-150-p29-1', 0, 19, 'nist-sp-800-150', 'Final', '8B6C47E41E4223AECFDFF129974417B06185CED8FF0114494F7472664F58AA25', 'v1', '{"source_id": "nist-sp-800-150", "version": "Final", "corpus_version": "v1", "batch": "batch-001"}')
