VALUES ('doc-nist-800-150-p40-1', 'doc-nist-800-150', '', 40, 'NIST SP 800-150 GUIDE TO CYBER THREAT INFORMATION SHARING 32 This publication is available free of charge from: http://dx.doi.org/10.6028/NIST.SP.800-150', 'kb-doc-nist-800-150-p40-1', 0, 19, 'nist-sp-800-150', 'Final', '0300BB82563553E900B38DA8E2D7880893CA40D08B1AE5694541DE690F52B459', 'v1', '{"source_id": "nist-sp-800-150", "version": "Final", "corpus_version": "v1", "batch": "batch-001"}')
