VALUES ('doc-nist-800-86-p3-2', 'doc-nist-800-86', '', 3, 'U.S. Department of Commerce Carlos M. Gutierrez, Secretary Technology Administration Robert C. Cresanti, Under Secretary of Commerce for Technology National Institute of Standards and Technology William A. Jeffrey, Director', 'kb-doc-nist-800-86-p3-2', 0, 29, 'nist-sp-800-86', 'Final', '4FF9214CD81F1AF8E7F82D8F5D40CC19BFA0303589B436A825A122D3E94579C7', 'v1', '{"source_id": "nist-sp-800-86", "version": "Final", "corpus_version": "v1", "batch": "batch-001"}')
