INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-nist-800-86-p4-1', 'doc-nist-800-86', '', 4, 'The Information Technology Laboratory (ITL) at the National Institute of Standards and Technology (NIST) promotes the U.S. economy and public welfare by providing technical leadership for the nations measurement and standards infrastructure. ITL develops tests, test methods, reference data, proof of concept implementations, and technical analysis to advance the development and productive use of information technology. ITLs responsibilities include the development of technical, physical, administrative, and management standards and guidelines for the cost-effective security and privacy of sensitive unclassified information in Federal computer systems. This Special Publication 800-series reports on ITLs research, guidance, and outreach efforts in computer security and its collaborative activities with industry, government, and academic organizations.', 'kb-doc-nist-800-86-p4-1', 0, 109, 'nist-sp-800-86', 'Final', '396DD21023C3A4DFFB95B4D6BA487D895E47988B0FF9EC36333E52F9E35E2BA0', 'v1', '{"source_id": "nist-sp-800-86", "version": "Final", "corpus_version": "v1", "batch": "batch-001"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-nist-800-86-p4-2', 'doc-nist-800-86', '', 4, 'Certain commercial entities, equipment, or materials may be identified in this document in order to describe an experimental procedure or concept adequately. Such identification is not intended to imply recommendation or endorsement by the National Institute of Standards and Technology, nor is it intended to imply that the entities, materials, or equipment are necessarily the best available for the purpose. National Institute of Standards and Technology Special Publication 800-86 Natl. Inst. Stand. Technol. Spec. Publ. 800-86, 121 pages (August 2006)', 'kb-doc-nist-800-86-p4-2', 0, 80, 'nist-sp-800-86', 'Final', '23D1F24CFB8145006583E80D959992430AF0E0FBC2F811F954CAAABAFA51BA88', 'v1', '{"source_id": "nist-sp-800-86", "version": "Final", "corpus_version": "v1", "batch": "batch-001"}')
