VALUES ('doc-nist-800-86-p8-4', 'doc-nist-800-86', '', 8, 'List of Tables Table 4-1. Commonly Used Media Types .............................................................................. 4-2', 'kb-doc-nist-800-86-p8-4', 0, 11, 'nist-sp-800-86', 'Final', 'D270B4DAF5DD5056DDA2D6D5ED70AB3455FAD799FB8A1BC9FE26685C52973DA8', 'v1', '{"source_id": "nist-sp-800-86", "version": "Final", "corpus_version": "v1", "batch": "batch-001"}')
