INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-nist-800-86-p33-3', 'doc-nist-800-86', '', 33, '15 For additional information regarding examination and analysis, see Examination of Digital Evidence: A Guide for Law Enforcement, which can be found at http://www.ncjrs.gov/pdffiles1/nij/199408.pdf. 4-1', 'kb-doc-nist-800-86-p33-3', 0, 25, 'nist-sp-800-86', 'Final', '7C060CB5A5A625575FC9513F640323CD457339E7014E497523293888A0E6C9D9', 'v1', '{"source_id": "nist-sp-800-86", "version": "Final", "corpus_version": "v1", "batch": "batch-001"}')
