INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-nist-800-86-p93-2', 'doc-nist-800-86', '', 93, '126 Malware databases are maintained by several vendors, including Computer Associates (http://www3.ca.com/securityadvisor/virusinfo/default.aspx), F-Secure (http://www.f-secure.com/virus-info/), Network Associates (http://vil.nai.com/vil/default.aspx), Sophos (http://www.sophos.com/virusinfo/analyses/), Symantec (http://securityresponse.symantec.com/avcenter/vinfodb.html), and Trend Micro (http://www.trendmicro.com/vinfo/virusencyclo/). 8-3', 'kb-doc-nist-800-86-p93-2', 0, 26, 'nist-sp-800-86', 'Final', '8E7BD3B8A560B43E03DA2ED74C0444F8B81A8D77ABCE8AFB650FF9532ED7EA3F', 'v1', '{"source_id": "nist-sp-800-86", "version": "Final", "corpus_version": "v1", "batch": "batch-001"}')
