INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-nist-800-86-p96-1', 'doc-nist-800-86', '', 96, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE examining, and analyzing different types of data sources are fundamentally different. Many applications have data captured in data files, OSs, and network traffic. ! Organizations should be aware of the technical and logistical complexity of analysis. A single event can generate records on many different data sources and produce more information than analysts can feasibly review. Tools such as SEM can assist analysts by bringing information from many data sources together in a single place.', 'kb-doc-nist-800-86-p96-1', 0, 83, 'nist-sp-800-86', 'Final', 'E070C18A9E1EC9D7228112DAA3EBCEE086E31710DB448E5F7AAD8C5815EB3BCF', 'v1', '{"source_id": "nist-sp-800-86", "version": "Final", "corpus_version": "v1", "batch": "batch-001"}')
