VALUES ('doc-nist-800-86-p109-1', 'doc-nist-800-86', '', 109, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE Appendix DAcronyms Selected acronyms used in the Guide to Integrating Forensic Techniques into Incident Response are defined below.', 'kb-doc-nist-800-86-p109-1', 0, 26, 'nist-sp-800-86', 'Final', '4A2F71CA86599ED060506DE9F025C80C9C7C018ECC05637EEFBC47D95E930F1B', 'v1', '{"source_id": "nist-sp-800-86", "version": "Final", "corpus_version": "v1", "batch": "batch-001"}')
