VALUES ('doc-cisa-kev-record-1', 'doc-cisa-kev', 'KEV record', NULL, '{"cveID": "CVE-2023-49105", "cwes": ["CWE-287"], "dateAdded": "2026-08-27", "dueDate": "2026-08-30", "knownRansomwareCampaignUse": "Unknown", "notes": "https://owncloud.org/security ; https://owncloud.com/security-advisories/webdav-api-authentication-bypass-using-pre-signed-urls/ ; BOD 26-04: https://www.cisa.gov/news-events/directives/bod-26-04-prioritizing-security-updates-based-risk ; Forensics Triage Requirements: https://www.cisa.gov/news-events/directives/bod-26-04-implementation-guidance-prioritizing-security-updates-based-risk ; https://nvd.nist.gov/vuln/detail/CVE-2023-49105", "product": "ownCloud", "requiredAction": "Apply mitigations in accordance with vendor instructions, ensuring compliance with CISA’s BOD 26-04 Prioritizing Security Updates Based on Risk (see URL in Notes) guidance and CISA’s “Forensics Triage Requirements” (see URL in Notes). Follow applicable BOD 26-04 guidance for cloud services or discontinue use of the product if mitigations are unavailable. Stakeholders are responsible for evaluating each asset''s internet exposure and ensuring adherence to BOD 26-04 patching guidelines.", "shortDescription": "ownCloud contains an improper authentication vulnerability that allows an attacker to access, modify, or delete any file without authentication if the username of a victim is known, and the victim has no signing-key configured.", "vendorProject": "ownCloud", "vulnerabilityName": "ownCloud Improper Authentication Vulnerability"}', 'kb-doc-cisa-kev-record-1', 0, 138, 'cisa-kev', 'Current feed at retrieval', 'E080CB4C15642E55A025221F096EBBC56D18A7BAA8ABE22F2BF0C346FBCB3421', 'v1', '{"source_id": "cisa-kev", "version": "Current feed at retrieval", "corpus_version": "v1", "batch": "batch-001"}')
