VALUES ('doc-cisa-kev-record-151', 'doc-cisa-kev', 'KEV record', NULL, '{"cveID": "CVE-2021-22681", "cwes": ["CWE-522"], "dateAdded": "2026-03-05", "dueDate": "2026-03-26", "knownRansomwareCampaignUse": "Unknown", "notes": "https://support.rockwellautomation.com/app/answers/answer_view/a_id/1130301/~/cve-2021-22681%3A-authentication-bypass-vulnerability-found-in-logix-controllers- ; https://www.cisa.gov/news-events/ics-advisories/icsa-21-056-03 ; https://nvd.nist.gov/vuln/detail/CVE-2021-22681", "product": "Multiple Products", "requiredAction": "Apply mitigations per vendor instructions, follow applicable BOD 22-01 guidance for cloud services, or discontinue use of the product if mitigations are unavailable.", "shortDescription": "Multiple Rockwell products contain an insufficient protected credentials vulnerability. Studio 5000 Logix Designer software may allow a key to be discovered. This key is used to verify Logix controllers are communicating with Rockwell Automation design software. If successfully exploited, this vulnerability could allow an unauthorized application to connect with Logix controllers. To leverage this vulnerability, an unauthorized user would require network access to the controller.", "vendorProject": "Rockwell", "vulnerabilityName": "Rockwell Multiple Products Insufficient Protected Credentials Vulnerability"}', 'kb-doc-cisa-kev-record-151', 0, 119, 'cisa-kev', 'Current feed at retrieval', '6791C58A1936464C0E4D100155AC8160F76E6B7BD684CDCB2E3B1CB23056B51E', 'v1', '{"source_id": "cisa-kev", "version": "Current feed at retrieval", "corpus_version": "v1", "batch": "batch-001"}')
