VALUES ('doc-cisa-kev-record-157', 'doc-cisa-kev', 'KEV record', NULL, '{"cveID": "CVE-2022-20775", "cwes": ["CWE-25", "CWE-282"], "dateAdded": "2026-02-25", "dueDate": "2026-02-27", "knownRansomwareCampaignUse": "Unknown", "notes": "CISA Mitigation Instructions: https://www.cisa.gov/news-events/directives/ed-26-03-mitigate-vulnerabilities-cisco-sd-wan-systems ; https://www.cisa.gov/news-events/directives/supplemental-direction-ed-26-03-hunt-and-hardening-guidance-cisco-sd-wan-systems ; https://www.cisco.com/c/en/us/support/docs/csa/cisco-sa-sd-wan-priv-E6e8tEdF.html ; https://nvd.nist.gov/vuln/detail/CVE-2022-20775", "product": "SD-WAN", "requiredAction": "Please adhere to CISA’s guidelines to assess exposure and mitigate risks associated with Cisco SD-WAN devices as outlines in CISA’s Emergency Directive 26-03 (URL listed below in Notes) and CISA’s “Hunt & Hardening Guidance for Cisco SD-WAN Devices (URL listed below in Notes). Adhere to the applicable BOD 22-01 guidance for cloud services or discontinue use of the product if mitigations are not available.", "shortDescription": "Cisco SD-WAN CLI contains a path traversal vulnerability that could allow an authenticated local attacker to gain elevated privileges via improper access controls on commands within the application CLI. A successful exploit could allow the attacker to execute arbitrary commands as the root user.", "vendorProject": "Cisco", "vulnerabilityName": "Cisco SD-WAN Path Traversal Vulnerability"}', 'kb-doc-cisa-kev-record-157', 0, 142, 'cisa-kev', 'Current feed at retrieval', 'A005EA5CA38AAE9C4E9787EADBF064E864150040D61A0935C4EB1CFE0E03CE15', 'v1', '{"source_id": "cisa-kev", "version": "Current feed at retrieval", "corpus_version": "v1", "batch": "batch-001"}')
