VALUES ('doc-cisa-kev-record-189', 'doc-cisa-kev', 'KEV record', NULL, '{"cveID": "CVE-2026-23760", "cwes": ["CWE-288"], "dateAdded": "2026-01-26", "dueDate": "2026-02-16", "knownRansomwareCampaignUse": "Known", "notes": "https://www.smartertools.com/smartermail/release-notes/current ; https://nvd.nist.gov/vuln/detail/CVE-2026-23760", "product": "SmarterMail", "requiredAction": "Apply mitigations per vendor instructions, follow applicable BOD 22-01 guidance for cloud services, or discontinue use of the product if mitigations are unavailable.", "shortDescription": "SmarterTools SmarterMail contains an authentication bypass using an alternate path or channel vulnerability in the password reset API. The force-reset-password endpoint permits anonymous requests and fails to verify the existing password or a reset token when resetting system administrator accounts. This could allow an unauthenticated attacker to supply a target administrator username and a new password to reset the account, resulting in full administrative compromise of the SmarterMail instance.", "vendorProject": "SmarterTools", "vulnerabilityName": "SmarterTools SmarterMail Authentication Bypass Using an Alternate Path or Channel Vulnerability"}', 'kb-doc-cisa-kev-record-189', 0, 124, 'cisa-kev', 'Current feed at retrieval', 'DDF794F34C8C3CAFFF44C6E6E988DC965F11EE4C49FD8D732557D03ACD5FAB18', 'v1', '{"source_id": "cisa-kev", "version": "Current feed at retrieval", "corpus_version": "v1", "batch": "batch-001"}')
