VALUES ('doc-cisa-kev-record-209', 'doc-cisa-kev', 'KEV record', NULL, '{"cveID": "CVE-2025-14611", "cwes": ["CWE-798"], "dateAdded": "2025-12-15", "dueDate": "2026-01-05", "knownRansomwareCampaignUse": "Unknown", "notes": "https://www.centrestack.com/p/gce_latest_release.html ; https://access.triofox.com/releases_history/; https://support.centrestack.com/hc/en-us/articles/360007159054-Hardening-the-CentreStack-Cluster#h_01JQRV57T37HJFQZKBZH9NBXQP ; https://nvd.nist.gov/vuln/detail/CVE-2025-14611", "product": "CentreStack and Triofox", "requiredAction": "Apply mitigations per vendor instructions, follow applicable BOD 22-01 guidance for cloud services, or discontinue use of the product if mitigations are unavailable.", "shortDescription": "Gladinet CentreStack and TrioFox contain a hardcoded cryptographic keys vulnerability for their implementation of the AES cryptoscheme. This vulnerability degrades security for public exposed endpoints that may make use of it and may offer arbitrary local file inclusion when provided a specially crafted request without authentication.", "vendorProject": "Gladinet", "vulnerabilityName": "Gladinet CentreStack and Triofox Hard Coded Cryptographic Vulnerability"}', 'kb-doc-cisa-kev-record-209', 0, 103, 'cisa-kev', 'Current feed at retrieval', 'CD0BDC88C27F9F52038971DE837B521BABD223E9EFEA3189EAEEF982114F8B31', 'v1', '{"source_id": "cisa-kev", "version": "Current feed at retrieval", "corpus_version": "v1", "batch": "batch-001"}')
