VALUES ('doc-cisa-kev-record-210', 'doc-cisa-kev', 'KEV record', NULL, '{"cveID": "CVE-2025-43529", "cwes": ["CWE-416"], "dateAdded": "2025-12-15", "dueDate": "2026-01-05", "knownRansomwareCampaignUse": "Unknown", "notes": "https://support.apple.com/en-us/125884 ; https://support.apple.com/en-us/125892 ; https://support.apple.com/en-us/125885 ; https://support.apple.com/en-us/125886 ; https://support.apple.com/en-us/125889 ; https://nvd.nist.gov/vuln/detail/CVE-2025-43529", "product": "Multiple Products", "requiredAction": "Apply mitigations per vendor instructions, follow applicable BOD 22-01 guidance for cloud services, or discontinue use of the product if mitigations are unavailable.", "shortDescription": "Apple iOS, iPadOS, macOS, and other Apple products contain a use-after-free vulnerability in WebKit. Processing maliciously crafted web content may lead to memory corruption. This vulnerability could impact HTML parsers that use WebKit, including but not limited to Apple Safari and non-Apple products which rely on WebKit for HTML processing.", "vendorProject": "Apple", "vulnerabilityName": "Apple Multiple Products Use-After-Free WebKit Vulnerability"}', 'kb-doc-cisa-kev-record-210', 0, 109, 'cisa-kev', 'Current feed at retrieval', 'A76FD6468352024F4B67BD48A384D5AE9842780F92F18A7293B4BCD0EAF4F264', 'v1', '{"source_id": "cisa-kev", "version": "Current feed at retrieval", "corpus_version": "v1", "batch": "batch-001"}')
