VALUES ('doc-cisa-kev-record-267', 'doc-cisa-kev', 'KEV record', NULL, '{"cveID": "CVE-2025-20352", "cwes": ["CWE-121"], "dateAdded": "2025-09-29", "dueDate": "2025-10-20", "knownRansomwareCampaignUse": "Unknown", "notes": "https://sec.cloudapps.cisco.com/security/center/content/CiscoSecurityAdvisory/cisco-sa-snmp-x4LPhte ; https://nvd.nist.gov/vuln/detail/CVE-2025-20352", "product": "IOS and IOS XE", "requiredAction": "Apply mitigations per vendor instructions, follow applicable BOD 22-01 guidance for cloud services, or discontinue use of the product if mitigations are unavailable.", "shortDescription": "Cisco IOS and IOS XE contains a stack-based buffer overflow vulnerability in the Simple Network Management Protocol (SNMP) subsystem that could allow for denial of service or remote code execution. A successful exploit could allow a low-privileged attacker to cause the affected system to reload, resulting in a DoS condition, or allow a high-privileged attacker to execute arbitrary code as the root user and obtain full control of the affected system.", "vendorProject": "Cisco", "vulnerabilityName": "Cisco IOS and IOS XE Software SNMP Denial of Service and Remote Code Execution Vulnerability"}', 'kb-doc-cisa-kev-record-267', 0, 133, 'cisa-kev', 'Current feed at retrieval', '0491E698D77AAD5C41089DADFC4F5DED435AC7A410FB7CC6ADF189117D24C850', 'v1', '{"source_id": "cisa-kev", "version": "Current feed at retrieval", "corpus_version": "v1", "batch": "batch-001"}')
