VALUES ('doc-cisa-kev-record-302', 'doc-cisa-kev', 'KEV record', NULL, '{"cveID": "CVE-2025-49704", "cwes": ["CWE-94"], "dateAdded": "2025-07-22", "dueDate": "2025-07-23", "knownRansomwareCampaignUse": "Known", "notes": "CISA Mitigation Instructions: https://www.cisa.gov/news-events/alerts/2025/07/20/microsoft-releases-guidance-exploitation-sharepoint-vulnerability-cve-2025-53770; https://www.microsoft.com/en-us/security/blog/2025/07/22/disrupting-active-exploitation-of-on-premises-sharepoint-vulnerabilities/ ; https://msrc.microsoft.com/update-guide/vulnerability/CVE-2025-49704 ; https://nvd.nist.gov/vuln/detail/CVE-2025-49704", "product": "SharePoint", "requiredAction": "Disconnect public-facing versions of SharePoint Server that have reached their end-of-life (EOL) or end-of-service (EOS) to include SharePoint Server 2013 and earlier versions. For supported versions, please follow the mitigations according to CISA (URL listed below in Notes) and vendor instructions (URL listed below in Notes). Adhere to the applicable BOD 22-01 guidance for cloud services or discontinue use of the product if mitigations are not available.", "shortDescription": "Microsoft SharePoint contains a code injection vulnerability that could allow an authorized attacker to execute code over a network. This vulnerability could be chained with CVE-2025-49706. CVE-2025-53770 is a patch bypass for CVE-2025-49704, and the updates for CVE-2025-53770 include more robust protection than those for CVE-2025-49704.", "vendorProject": "Microsoft", "vulnerabilityName": "Microsoft SharePoint Code Injection Vulnerability"}', 'kb-doc-cisa-kev-record-302', 0, 145, 'cisa-kev', 'Current feed at retrieval', 'DFC281A8C2ECFB310BD442CB8D010D7139633E16A73677D872B6C679EB107C13', 'v1', '{"source_id": "cisa-kev", "version": "Current feed at retrieval", "corpus_version": "v1", "batch": "batch-001"}')
