VALUES ('doc-cisa-kev-record-303', 'doc-cisa-kev', 'KEV record', NULL, '{"cveID": "CVE-2025-49706", "cwes": ["CWE-287"], "dateAdded": "2025-07-22", "dueDate": "2025-07-23", "knownRansomwareCampaignUse": "Known", "notes": "CISA Mitigation Instructions: https://www.cisa.gov/news-events/alerts/2025/07/20/microsoft-releases-guidance-exploitation-sharepoint-vulnerability-cve-2025-53770 ; https://www.microsoft.com/en-us/security/blog/2025/07/22/disrupting-active-exploitation-of-on-premises-sharepoint-vulnerabilities/ ; https://msrc.microsoft.com/update-guide/vulnerability/CVE-2025-49706 ; https://nvd.nist.gov/vuln/detail/CVE-2025-49706", "product": "SharePoint", "requiredAction": "Disconnect public-facing versions of SharePoint Server that have reached their end-of-life (EOL) or end-of-service (EOS) to include SharePoint Server 2013 and earlier versions. For supported versions, please follow the mitigations according to CISA (URL listed below in Notes) and vendor instructions (URL listed below in Notes). Adhere to the applicable BOD 22-01 guidance for cloud services or discontinue use of the product if mitigations are not available.", "shortDescription": "Microsoft SharePoint contains an improper authentication vulnerability that allows an authorized attacker to perform spoofing over a network. Successfully exploitation could allow an attacker to view sensitive information and make some changes to disclosed information. This vulnerability could be chained with CVE-2025-49704. CVE-2025-53771 is a patch bypass for CVE-2025-49706, and the updates for CVE-2025-53771 include more robust protection than those for CVE-2025-49706.", "vendorProject": "Microsoft", "vulnerabilityName": "Microsoft SharePoint Improper Authentication Vulnerability"}', 'kb-doc-cisa-kev-record-303', 0, 162, 'cisa-kev', 'Current feed at retrieval', '644682A15A7B38D3807DDBD6558FA664772F2141AC83BF08CAD53553E48B710D', 'v1', '{"source_id": "cisa-kev", "version": "Current feed at retrieval", "corpus_version": 