VALUES ('doc-cisa-kev-record-325', 'doc-cisa-kev', 'KEV record', NULL, '{"cveID": "CVE-2025-32433", "cwes": ["CWE-306"], "dateAdded": "2025-06-09", "dueDate": "2025-06-30", "knownRansomwareCampaignUse": "Unknown", "notes": "This vulnerability affects a common open-source project, third-party library, or a protocol used by different products. For more information, please see: https://github.com/erlang/otp/security/advisories/GHSA-37cp-fgq5-7wc2 ; https://sec.cloudapps.cisco.com/security/center/content/CiscoSecurityAdvisory/cisco-sa-erlang-otp-ssh-xyZZy ; https://nvd.nist.gov/vuln/detail/CVE-2025-32433", "product": "Erlang/OTP", "requiredAction": "Apply mitigations per vendor instructions, follow applicable BOD 22-01 guidance for cloud services, or discontinue use of the product if mitigations are unavailable.", "shortDescription": "Erlang Erlang/OTP SSH server contains a missing authentication for critical function vulnerability. This could allow an attacker to execute arbitrary commands without valid credentials, potentially leading to unauthenticated remote code execution (RCE). By exploiting a flaw in how SSH protocol messages are handled, a malicious actor could gain unauthorized access to affected systems. This vulnerability could affect various products that implement Erlang/OTP SSH server, including—but not limited to—Cisco, NetApp, and SUSE.", "vendorProject": "Erlang", "vulnerabilityName": "Erlang Erlang/OTP SSH Server Missing Authentication for Critical Function Vulnerability"}', 'kb-doc-cisa-kev-record-325', 0, 148, 'cisa-kev', 'Current feed at retrieval', '217E2A26A7A4EBDA8B58A25943A6A5DF93C73650C865B0490979B4AA2C16FA49', 'v1', '{"source_id": "cisa-kev", "version": "Current feed at retrieval", "corpus_version": "v1", "batch": "batch-001"}')
