VALUES ('doc-cisa-kev-record-658', 'doc-cisa-kev', 'KEV record', NULL, '{"cveID": "CVE-2023-36851", "cwes": ["CWE-306"], "dateAdded": "2023-11-13", "dueDate": "2023-11-17", "knownRansomwareCampaignUse": "Unknown", "notes": "https://supportportal.juniper.net/s/article/2023-08-Out-of-Cycle-Security-Bulletin-Junos-OS-SRX-Series-and-EX-Series-Multiple-vulnerabilities-in-J-Web-can-be-combined-to-allow-a-preAuth-Remote-Code-Execution?language=en_US ;  https://nvd.nist.gov/vuln/detail/CVE-2023-36851", "product": "Junos OS", "requiredAction": "Apply mitigations per vendor instructions or discontinue use of the product if mitigations are unavailable.", "shortDescription": "Juniper Junos OS on SRX Series contains a missing authentication for critical function vulnerability that allows an unauthenticated, network-based attacker to cause limited impact to the file system integrity. With a specific request to webauth_operation.php that doesn''t require authentication, an attacker is able to upload arbitrary files via J-Web, leading to a loss of integrity for a certain part of the file system, which may allow chaining to other vulnerabilities.", "vendorProject": "Juniper", "vulnerabilityName": "Juniper Junos OS SRX Series Missing Authentication for Critical Function Vulnerability"}', 'kb-doc-cisa-kev-record-658', 0, 118, 'cisa-kev', 'Current feed at retrieval', '607C780309D5A069CFA441F03F5D80F168502629AB1E6D9203D08330660D7517', 'v1', '{"source_id": "cisa-kev", "version": "Current feed at retrieval", "corpus_version": "v1", "batch": "batch-001"}')
