VALUES ('doc-cisa-kev-record-662', 'doc-cisa-kev', 'KEV record', NULL, '{"cveID": "CVE-2023-46748", "cwes": ["CWE-89"], "dateAdded": "2023-10-31", "dueDate": "2023-11-21", "knownRansomwareCampaignUse": "Unknown", "notes": "https://my.f5.com/manage/s/article/K000137365 ;  https://nvd.nist.gov/vuln/detail/CVE-2023-46748", "product": "BIG-IP Configuration Utility", "requiredAction": "Apply mitigations per vendor instructions or discontinue use of the product if mitigations are unavailable.", "shortDescription": "F5 BIG-IP Configuration utility contains an SQL injection vulnerability that may allow an authenticated attacker with network access through the BIG-IP management port and/or self IP addresses to execute system commands. This vulnerability can be used in conjunction with CVE-2023-46747.", "vendorProject": "F5", "vulnerabilityName": "F5 BIG-IP Configuration Utility SQL Injection Vulnerability"}', 'kb-doc-cisa-kev-record-662', 0, 85, 'cisa-kev', 'Current feed at retrieval', 'C023BE3B34D9C21BCDAEC81AF8751777F065505839611AA1FF206CA501258A42', 'v1', '{"source_id": "cisa-kev", "version": "Current feed at retrieval", "corpus_version": "v1", "batch": "batch-001"}')
