VALUES ('doc-cisa-kev-record-663', 'doc-cisa-kev', 'KEV record', NULL, '{"cveID": "CVE-2023-46747", "cwes": ["CWE-288"], "dateAdded": "2023-10-31", "dueDate": "2023-11-21", "knownRansomwareCampaignUse": "Known", "notes": "https://my.f5.com/manage/s/article/K000137353;   https://nvd.nist.gov/vuln/detail/CVE-2023-46747", "product": "BIG-IP Configuration Utility", "requiredAction": "Apply mitigations per vendor instructions or discontinue use of the product if mitigations are unavailable.", "shortDescription": "F5 BIG-IP Configuration utility contains an authentication bypass using an alternate path or channel vulnerability due to undisclosed requests that may allow an unauthenticated attacker with network access to the BIG-IP system through the management port and/or self IP addresses to execute system commands. This vulnerability can be used in conjunction with CVE-2023-46748.", "vendorProject": "F5", "vulnerabilityName": "F5 BIG-IP Configuration Utility Authentication Bypass Vulnerability"}', 'kb-doc-cisa-kev-record-663', 0, 97, 'cisa-kev', 'Current feed at retrieval', '40E5683F41BF569DDBA5706ABEBFA5DF5D909F05F6F7B496C95145DDAEB5B805', 'v1', '{"source_id": "cisa-kev", "version": "Current feed at retrieval", "corpus_version": "v1", "batch": "batch-001"}')
