VALUES ('doc-cisa-kev-record-667', 'doc-cisa-kev', 'KEV record', NULL, '{"cveID": "CVE-2023-20198", "cwes": ["CWE-420"], "dateAdded": "2023-10-16", "dueDate": "2023-10-20", "knownRansomwareCampaignUse": "Unknown", "notes": "https://www.cisco.com/c/en/us/support/docs/ios-nx-os-software/ios-xe-dublin-17121/221128-software-fix-availability-for-cisco-ios.html;  https://nvd.nist.gov/vuln/detail/CVE-2023-20198", "product": "IOS XE Web UI", "requiredAction": "Verify that instances of Cisco IOS XE Web UI are in compliance with BOD 23-02 and apply mitigations per vendor instructions. For affected products (Cisco IOS XE Web UI exposed to the internet or to untrusted networks), follow vendor instructions to determine if a system may have been compromised and immediately report positive findings to CISA.", "shortDescription": "Cisco IOS XE Web UI contains a privilege escalation vulnerability in the web user interface that could allow a remote, unauthenticated attacker to create an account with privilege level 15 access. The attacker can then use that account to gain control of the affected device.", "vendorProject": "Cisco", "vulnerabilityName": "Cisco IOS XE Web UI Privilege Escalation Vulnerability"}', 'kb-doc-cisa-kev-record-667', 0, 132, 'cisa-kev', 'Current feed at retrieval', 'ED1DCF420F9B4175EFD03FDB4CF26504D229CCEF2F09318BFD9A9C9D0A8C3033', 'v1', '{"source_id": "cisa-kev", "version": "Current feed at retrieval", "corpus_version": "v1", "batch": "batch-001"}')
